"""The two tests pyparsing efd56db (issue #560) added, run standalone."""
import unittest

import pyparsing as pp
from pyparsing import testing as ppt


class Repeater(ppt.TestParseResultsAsserts, unittest.TestCase):
    def test_nested(self):
        LBRACE, RBRACE, SLASH = map(pp.Suppress, '{}/')
        tag_name = pp.Word(pp.alphanums + '_')
        open_tag = LBRACE + tag_name + RBRACE
        close_tag = LBRACE + SLASH + pp.match_previous_expr(tag_name) + RBRACE
        content = pp.Forward()
        content <<= (open_tag + pp.Group(content) + close_tag) | pp.Word(pp.alphas)
        for tst, expected in [('{a}xx{/a}', True), ('{a}{b}xx{/b}{/a}', True), ('{a}{b}{c}xx{/c}{/b}{/a}', True), ('{a}{b}xx{/a}{/b}', False), ('{a}{b}xx{/b}{/c}', False), ('{a}xx{/b}', False)]:
            if expected:
                content.parse_string(tst, parse_all=True)
            else:
                with self.assertRaisesParseException():
                    content.parse_string(tst, parse_all=True)

    def test_reused(self):
        first = pp.Word(pp.alphas)
        expr = first + pp.Suppress(':') + pp.match_previous_expr(first)
        self.assertParseAndCheckList(pp.OneOrMore(expr), 'a:a b:b c:c', ['a', 'a', 'b', 'b', 'c', 'c'])
        for tst, expected in [('d:d', True), ('e:f', False), ('g:g', True)]:
            if expected:
                self.assertParseAndCheckList(expr, tst, tst.split(':'))
            else:
                with self.assertRaisesParseException():
                    expr.parse_string(tst)


if __name__ == '__main__':
    unittest.main()

